"""Generate complete native-build normalization and wrapper HIA policy."""
from __future__ import annotations

import argparse
import ast
from pathlib import Path
import sys
import struct

ROOT = Path(__file__).resolve().parents[1]
if __package__ in (None, ''):
    sys.path.insert(0, str(ROOT))

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.generate_hia_machine_plan_control import (
    BODY as CONTROL_BODY, MAGIC, EMIT_MAGIC, ABI, OUTPUT)
from tools.generate_hia_core_lowering_control import emission, transport_helpers
from tools.hia_core_lowering_table import BODY as EXPAND_BODY, compress_table, reference_expand
from tools.hia_exception_delivery import BODY as EXCEPTION_BODY
from tools.hia_native_build_control import compile_policy, OPS


def table(policy):
    starts = {}
    count = 0
    for function in policy.functions:
        starts[function.mode] = count + 1
        count += len(function.instructions)
    data = bytearray(64 + len(policy.functions) * 32)
    for function in policy.functions:
        metadata = len(data)
        data += bytes((int(i in function.temporary_slots) |
                       (2 * int(i in function.cell_slots)))
                      for i in range(function.next_slot))
        for own, outer in function.captures.values():
            data += struct.pack('<H', own.slot)
        info = (len(function.parameters) |
                (int(function.kind == 'generator') << 16) |
                (len(function.captures) << 32))
        struct.pack_into('<4Q', data, 64 + (function.mode - 1) * 32,
                         starts[function.mode], function.next_slot, info, metadata)
    offsets_at = len(data)
    data += b'\0' * (4 * count)
    ordinal = 0
    for function in policy.functions:
        shift = starts[function.mode] - 1
        for instruction in function.instructions:
            struct.pack_into('<I', data, offsets_at + ordinal * 4, len(data))
            ordinal += 1
            kind = instruction['kind']
            if kind == 'effect':
                destinations, arguments = instruction['destinations'], instruction['arguments']
                raw, vector = instruction['raw'], instruction['vector']
                consume = instruction['consume']
                handler = instruction['handler']
                data += struct.pack('<6BH I H', 1, instruction['opcode'], len(destinations),
                                    len(arguments), len(raw), len(consume), len(vector),
                                    handler + shift if handler else 0, 0)
                for ref in (*destinations, *arguments):
                    data += struct.pack('<H', ref.slot)
                for value in raw:
                    data += struct.pack('<I', value)
                for ref in (*vector, *consume):
                    data += struct.pack('<H', ref.slot)
            elif kind == 'jump':
                data += struct.pack('<BI', 2, instruction['target'] + shift)
            elif kind == 'flag':
                data += struct.pack('<BII', 3, instruction['yes'] + shift,
                                    instruction['no'] + shift)
            elif kind in ('return', 'yield'):
                data += struct.pack('<BH', 4 if kind == 'return' else 5,
                                    instruction['value'].slot)
            elif kind == 'error_return':
                data += b'\6'
            else:
                raise ValueError('unrendered instruction')
    literals_at = len(data)
    data += b'\0' * (4 * len(policy.literals))
    for index, value in enumerate(policy.literals):
        struct.pack_into('<I', data, literals_at + 4 * index, len(data))
        if value is None:
            kind, raw = 0, b''
        elif type(value) is bool:
            kind, raw = 1, bytes((int(value),))
        elif type(value) is int:
            kind, raw = 2, str(value).encode('ascii')
        elif type(value) is bytes:
            kind, raw = 5, value
        elif type(value) is str:
            # CPython interns its ASCII name-character constants. Record that
            # representation in the immutable HIA-owned table, so the runtime
            # bridge does not infer a policy or change the object's identity.
            interned = all(c in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'
                           for c in value)
            kind, raw = (4 if interned else 3), value.encode('utf-8')
        else:
            raise ValueError('unrendered literal')
        data += struct.pack('<BQ', kind, len(raw)) + raw
    data += bytes((-len(data)) % 8)
    struct.pack_into('<8Q', data, 0, MAGIC, len(data), len(policy.functions), count,
                     64, offsets_at, literals_at, len(policy.literals))
    return bytes(data)


def program():
    return compile_policy((ROOT / 'tools/hia_native_build_policy.py').read_text())


def source():
    policy = program()
    data = table(policy)
    packed = compress_table(data)
    if reference_expand(packed) != data:
        raise AssertionError('native-build policy representation is not lossless')
    constants = {'MAGIC': MAGIC, 'EMIT_MAGIC': EMIT_MAGIC, 'ABI': ABI,
                 'OUTPUT_BYTES': OUTPUT, 'TABLE_BYTES': len(data),
                 'PACKED_BYTES': len(packed),
                 'WORKSPACE_BYTES': 1024 + 8 * max(fn.next_slot for fn in policy.functions),
                 **OPS}
    parsed = ast.parse(CONTROL_BODY + '\n' + transport_helpers() + '\n' +
                       emission(data, packed) + '\n' + EXPAND_BODY + '\n' + EXCEPTION_BODY)
    class Names(ast.NodeTransformer):
        def visit_Name(self, node):
            return ast.copy_location(ast.Constant(constants[node.id]), node) if node.id in constants else node
    return ast.fix_missing_locations(Names().visit(parsed))


def document():
    nodes = source().body
    names = {node.name: 'f' + str(index) for index, node in enumerate(nodes)}
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args], node.returns.id)
                  for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = Builder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name], 'params': [builder.param(v) for v in builder.params],
            'returns': [builder.returns], 'effects': ['read', 'write', 'trap'],
            'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8',
                                  'module': 'native_build', 'functions': functions})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path,
                        default=ROOT / 'examples/hia_bootstrap/native_build.hepta')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    raw = render_assembly(document()).encode()
    if args.check:
        if args.output.read_bytes() != raw:
            raise AssertionError('native-build HIA differs from its complete policy')
    else:
        args.output.write_bytes(raw)
    print(args.output)


if __name__ == '__main__':
    main()

tools/hia_core_emitter_control_policy.py.text:
"""Exact original six-method emitter policy; authoring input only.
Runtime uses the emitted HIA table and never imports this module.
"""

class _Emitter:
    def __init__(self, document, allowed_exports, block_order=None, foreign_buffer_exports=(), machine_plan=None):
        from .hia_machine_plan import code_options
        self.document, self.allowed_exports = document, allowed_exports
        self.c, self.symbols, self.exports, self.frames = Code(**code_options(machine_plan)), [], [], []
        self.machine_plan = machine_plan
        self.function_alignment = 1 if machine_plan is None else machine_plan.get("function_alignment", 1)
        self.indices = {fn["name"]: i for i, fn in enumerate(document["functions"])}
        self.serial = 0
        self.block_order = block_order or {}
        self.foreign_buffer_exports = dict(foreign_buffer_exports)

    def ordered_blocks(self, fn):
        """Realize the caller's checked layout; never choose a profitable order."""
        order = self.block_order.get(fn["name"])
        if order is None:
            return fn["blocks"]
        blocks = {block["id"]: block for block in fn["blocks"]}
        return [blocks[name] for name in order]

    def label(self, suffix):
        self.serial += 1
        return suffix + "_" + str(self.serial)

    def function_symbol(self, name):
        return "__hia_native_fn_" + str(self.indices[name])

    def wrapper(self, fn):
        name = fn["name"]
        if name in self.foreign_buffer_exports:
            from .hia_native_byte_abi import emit_wrapper
            emit_wrapper(self, fn, self.foreign_buffer_exports[name])
            return
        if (name not in self.allowed_exports
                or any(p["type"] not in set(WIDTHS) | {"bool"} for p in fn["params"])
                or len(fn["returns"]) > 1
                or any(t not in set(WIDTHS) | {"bool", "unit"} for t in fn["returns"])):
            return
        if name in IMPORTS or name in _LOADER_HOOKS or name.startswith("__hia_"):
            _reject("export conflicts with the closed runtime or loader ABI", "E_HIA_PROGRAM_ABI")
        count = len(fn["params"])
        frame = ((count + 1) * 8 + 15) & -16
        if frame > MAX_FRAME_BYTES:
            _reject("entry wrapper exceeds the stack budget", "E_HIA_PROGRAM_LIMIT")
        c = self.c
        begin = len(c.data)
        _prologue(c, frame)
        input_slot, result_slot = -frame, -8
        # rax is the only scratch until every incoming argument is saved.
        for i, param in enumerate(fn["params"]):
            if i < len(_ARG_REGS):
                c.mov_rr("rax", _ARG_REGS[i])
            else:
                c.load("rax", "rbp", 16 + 8 * (i - len(_ARG_REGS)))
            _normalize(c, "rax", param["type"])
            c.store("rbp", input_slot + i * 8, "rax")
        c.lea("rdi", "rbp", input_slot); c.lea("rsi", "rbp", result_slot)
        c.call(self.function_symbol(name))
        if fn["returns"] and fn["returns"] != ["unit"]:
            c.load("rax", "rbp", result_slot)
            _normalize(c, "rax", fn["returns"][0])
        c.leave(); c.ret()
        self.symbols.append({"name": name, "offset": begin, "size": len(c.data) - begin, "global": True})
        self.exports.append(name)

    def render(self):
        # Future Core additions require an explicit lowering review. A growing
        # verifier registry cannot silently widen this backend through prefixes.
        if self.document["schema"] not in CORE_SCHEMAS:
            _reject("Core schema lacks a reviewed direct lowering", "E_HIA_PROGRAM_PROFILE")
        for fn in self.document["functions"]:
            types = [p["type"] for p in fn["params"]] + fn["returns"]
            for block in fn["blocks"]:
                types.extend(p["type"] for p in block["params"])
                if block["term"]["op"] not in {"ret", "jump", "branch", "trap"}:
                    _reject("terminator lacks a reviewed direct lowering", "E_HIA_PROGRAM_PROFILE")
                for instruction in block["ops"]:
                    if instruction["op"] not in SUPPORTED_OPCODES:
                        _reject("opcode lacks a reviewed direct lowering", "E_HIA_PROGRAM_PROFILE")
                    types.extend(p["type"] for p in instruction["out"])
            if any(typ not in _TYPES for typ in types):
                _reject("type lacks a reviewed direct lowering", "E_HIA_PROGRAM_PROFILE")
        functions = self.document["functions"]
        if self.machine_plan is not None and "function_order" in self.machine_plan:
            by_name = {fn["name"]: fn for fn in functions}
            functions = [by_name[name] for name in self.machine_plan["function_order"]]
        for fn in functions:
            self.c.align(self.function_alignment)
            _Function(self, fn, self.indices[fn["name"]]).render()
        for fn in functions:
            self.c.align(self.function_alignment)
            self.wrapper(fn)
        missing = set(self.document.get("exports", [])) - set(self.exports)
        if missing:
            _reject("explicit exports have signatures outside the native C ABI: " + ", ".join(sorted(missing)), "E_HIA_PROGRAM_ABI")
        if not 1 <= len(self.exports) <= 128:
            _reject("native profile requires between 1 and 128 admitted entrypoints")
        if len(self.c.data) > MAX_TEXT_BYTES:
            _reject("direct code exceeds the text budget", "E_HIA_PROGRAM_LIMIT")
        text, relocations = self.c.finalize()
        obj = write_elf_object(text, self.symbols, relocations,
                               text_alignment=max(16, self.function_alignment))
        return text, obj

def _native_globals():
    return {'MAX_TEXT_BYTES': 16777216, 'MAX_FRAME_BYTES': 65536, '_ARG_REGS': ('rdi', 'rsi', 'rdx', 'rcx', 'r8', 'r9')}
